from z3 import *
import time

solver = Solver()
solver.set("timeout", 50000)

# Use integers
L = [Int(f"L_{i}") for i in range(15)]

# Domain constraints
for i in range(15):
    solver.add(L[i] >= 0, L[i] <= 27)

# All different
for i in range(15):
    for j in range(i+1, 15):
        solver.add(L[i] != L[j])

# Edge differences using If
def abs_diff(a, b):
    return If(a > b, a - b, b - a)

E = []
for g in range(5):
    E.append(abs_diff(L[g*3], L[g*3+1]))
    E.append(abs_diff(L[g*3], L[g*3+2]))
    E.append(abs_diff(L[g*3+1], L[g*3+2]))
for g in range(4):
    for i in range(3):
        E.append(abs_diff(L[g*3+i], L[(g+1)*3+i]))

# All edge differences distinct
for i in range(27):
    for j in range(i+1, 27):
        solver.add(E[i] != E[j])

# Edge differences in [1, 27]
for i in range(27):
    solver.add(E[i] >= 1, E[i] <= 27)

start = time.time()
result = solver.check()
print(f"Result: {result}, time: {time.time()-start:.2f}s")

if result == sat:
    m = solver.model()
    solution = [m[L[i]].as_long() for i in range(15)]
    print(f"Solution: {solution}")

    # Verify
    edge_vals = []
    for g in range(5):
        edge_vals.append(abs(solution[g*3] - solution[g*3+1]))
        edge_vals.append(abs(solution[g*3] - solution[g*3+2]))
        edge_vals.append(abs(solution[g*3+1] - solution[g*3+2]))
    for g in range(4):
        for i in range(3):
            edge_vals.append(abs(solution[g*3+i] - solution[(g+1)*3+i]))
    print(f"Edge labels sorted: {sorted(edge_vals)}")
    print(f"Distinct: {len(set(edge_vals))}")
else:
    print("UNSAT or timeout")
